  ]},
  {"clause_id": "c052", "issues": [
    {"issue": "The \"notwithstanding the foregoing\" carve-out for Reimbursement Amounts cannot be given full effect alongside c051's subordination of XLCA's recoveries to prior indefeasible payment in full of the Owners, since Reimbursement Amounts under c030 are largely the same sums recovered through subrogation. The priority between the two is left to construction.", "type": 2, "prob": 0.24}
  ]},
  {"clause_id": "c053", "issues": [
