  ]},
  {"clause_id": "c065", "issues": []},
  {"clause_id": "c066", "issues": [
    {"issue": "The certification rests on entitlement to demand \"pursuant to Section 3.20 of the Indenture,\" a cross-reference to an instrument not attached to the Policy and not verifiable from the Endorsement or the Insurance and Indemnity Agreement. If the Indenture's claim provision is numbered otherwise, the form certifies to nothing.", "type": 2, "prob": 0.20}
  ]},
  {"clause_id": "c067", "issues": [
